    R(0, 0, w, 88, bg, 6, g, { stroke: INK, 'stroke-width': 7 }); TX(w / 2, 64, text.toUpperCase(), 58, INK, g, { 'font-family': 'Anton, Impact, sans-serif' });
    tl().set(g, { opacity: 1 }, at); tl().set(g, { opacity: 0 }, at + dur); GR._ov = GR._ov || []; GR._ov.push(g); return g; };
